'use strict';

// MODULES //

var tape = require( 'tape' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var isEqual = require( './../lib/words.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isEqual, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function tests whether two 64-bit unsigned integers are equal', function test( t ) {
	var v;

	v = isEqual( 1, 2, 1, 2 );
	t.strictEqual( v, true, 'returns expected value' );

	v = isEqual( 1, 2, 1, 3 );
	t.strictEqual( v, false, 'returns expected value' );

	v = isEqual( 1, 2, 2, 2 );
	t.strictEqual( v, false, 'returns expected value' );

	v = isEqual( UINT32_MAX, UINT32_MAX, UINT32_MAX, UINT32_MAX );
	t.strictEqual( v, true, 'returns expected value' );

	v = isEqual( UINT32_MAX, UINT32_MAX, UINT32_MAX, UINT32_MAX - 1 );
	t.strictEqual( v, false, 'returns expected value' );

	v = isEqual( UINT32_MAX, UINT32_MAX, UINT32_MAX - 1, UINT32_MAX );
	t.strictEqual( v, false, 'returns expected value' );

	t.end();
});
